std::vector<int> tails;              // tails[k] = 长度 k+1 的递增子序列的最小结尾
for (int x : a) {
    auto it = std::lower_bound(tails.begin(), tails.end(), x);  // 严格递增
    if (it == tails.end()) tails.push_back(x);
    else                   *it = x;
}
return tails.size();
// 若允许相等（非严格），把 lower_bound 换成 upper_bound

int n = a.size(), m = b.size();
std::vector<std::vector<int>> dp(n + 1, std::vector<int>(m + 1, 0));
for (int i = 0; i <= n; ++i) dp[i][0] = i;   // 全删
for (int j = 0; j <= m; ++j) dp[0][j] = j;   // 全插

for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) {
        if (a[i - 1] == b[j - 1]) {
            dp[i][j] = dp[i - 1][j - 1];
        } else {
            dp[i][j] = 1 + std::min({dp[i - 1][j],      // 删
                                     dp[i][j - 1],      // 插
                                     dp[i - 1][j - 1]});// 换
        }
    }
}
return dp[n][m];

std::vector<int> dp(W + 1, 0);
for (int i = 0; i < n; ++i) {
    for (int j = W; j >= w[i]; --j) {   // 倒序！
        dp[j] = std::max(dp[j], dp[j - w[i]] + v[i]);
    }
}
return dp[W];

std::vector<int> dp(W + 1, 0);
for (int i = 0; i < n; ++i) {
    for (int j = w[i]; j <= W; ++j) {   // 正序！与 0-1 背包的唯一区别
        dp[j] = std::max(dp[j], dp[j - w[i]] + v[i]);
    }
}
return dp[W];

struct DSU {
    std::vector<int> p, rnk;
    DSU(int n) : p(n + 1), rnk(n + 1, 0) {
        for (int i = 1; i <= n; ++i) p[i] = i;
    }
    int find(int x) {
        int root = x;
        while (p[root] != root) root = p[root];   // 找根
        while (p[x] != root) {                    // 压缩路径
            int nx = p[x];
            p[x] = root;
            x = nx;
        }
        return root;
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;                 // 已连通 → 会成环
        if (rnk[a] < rnk[b]) std::swap(a, b);
        p[b] = a;
        if (rnk[a] == rnk[b]) ++rnk[a];
        return true;
    }
};

