int full = 1 << n;
std::vector<int> dp(full, INF);
dp[0] = 0;
for (int mask = 0; mask < full; ++mask) {
    if (dp[mask] == INF) continue;
    for (int i = 0; i < n; ++i) {
        if ((mask >> i) & 1) continue;          // 已选过
        int nmask = mask | (1 << i);
        dp[nmask] = std::min(dp[nmask], dp[mask] + cost(mask, i));
    }
}
